const tea = {
  name: "tea",
  price: 3,
  cost(count, tip) {
    return `${this.name}: ${this.price * count + tip}`;
  },
};

const cake = { name: "cake", price: 5 };

console.log(tea.cost.call(cake, 2, 1));
console.log(tea.cost.apply(cake, [1, 0]));
console.log(tea.cost.apply(tea, [2, 2]));
console.log(tea.cost.call(tea, [2, 2]));
